CREATE TYPE "public"."ledger_account_type" AS ENUM('ASSET', 'LIABILITY', 'INCOME', 'CONTRA_INCOME', 'EXPENSE');--> statement-breakpoint
CREATE TYPE "public"."ledger_normal_balance" AS ENUM('DEBIT', 'CREDIT');--> statement-breakpoint
