CREATE TYPE "public"."refund_reason" AS ENUM('DUPLICATE_PAYMENT', 'CORRUPT_FILE', 'NOT_AS_DESCRIBED', 'PLATFORM_ERROR', 'OWNER_DISCRETION');--> statement-breakpoint
CREATE TYPE "public"."refund_status" AS ENUM('REQUESTED', 'APPROVED', 'REJECTED', 'PAID', 'WITHDRAWN');--> statement-breakpoint
